    V8.Cache.Get('Microi:' + V8.OsClient + ':Ops:ReadinessProbe');
    return { Code: 1, Data: { Status: 'Ready' } };
} catch (error) { return { Code: 0, Data: { Status: 'NotReady' } }; }

